/// The items below are pub(crate).
/// The open completion popup.
#[derive(Clone, Debug, PartialEq, Eq)]
struct CompletionPopup {
    pub items: Vec<String>,
    pub selected: usize,
}

/// The items below are pub(crate).
/// None for an empty list. `selected` starts at 0.
fn popup_from_words(words: Vec<String>, limit: usize) -> Option<CompletionPopup>
impl CompletionPopup {
    /// Move the selection with wrap around.
    pub fn step(&mut self, delta: i32);
    pub fn accepted(&self) -> &str;
}
/// Server items first, then buffer words that are not already there, at most `limit`.
fn merge_completions(server: Vec<String>, buffer_words: Vec<String>, limit: usize) -> Vec<String>
/// The part of `item` after `prefix`, or None when `item` does not start with `prefix` or adds nothing.
fn suffix_for(item: &str, prefix: &str) -> Option<String>
